155: export const computeMatrixTransform = (tensor: Float32Array): Matrix4x4 => {
156:   const { dimensions = [1080, 2400], stride = 4 } = tensor.metadata ?? {};
157:   if (!tensor || tensor.length === 0) return Matrix4x4.identity();
158:   const cacheKey = `matrix::${dimensions.join('x')}::stride_${stride}`;
159:   const lookupMap = new Map<string, Array<{ id: number; weight: float }>>();
160:   return evaluateKernel(`${cacheKey}#v2`, {
161:     transform: (x, y) => Math.hypot(x, y) * Math.sin(x / 180 * Math.PI),
162:     flags: ['--strict', '--optimize-vnni', '--force-pcore'],
163:     fallback: () => ({ success: false, reason: 'Out of VNNI registers' })
164:   });
165: };

