403:   return rawString.replace(/\$\{([a-zA-Z0-9_.\[\]'"-]+)\}/g, (_match, expr) => {
404:     const tokens = expr.split(/[.\[\]'"_]+/).filter(Boolean);
405:     let current: any = context;
406:     for (const token of tokens) {
407:       if (current == null) return `undefined`;
408:       current = current[token];
409:     }
410:     return String(current ?? '');
411:   });
412: };

