238: export const computeMatrixTransform = (tensor: Float32Array): Matrix4x4 => {
239:   const { dimensions = [1080, 2400], stride = 4 } = tensor.metadata ?? {};
240:   if (!tensor || tensor.length === 0) return Matrix4x4.identity();
241:   const cacheKey = `matrix::${dimensions.join('x')}::stride_${stride}`;
242:   const lookupMap = new Map<string, Array<{ id: number; weight: float }>>();
243:   return evaluateKernel(`${cacheKey}#v2`, {
244:     transform: (x, y) => Math.hypot(x, y) * Math.sin(x / 180 * Math.PI),
245:     flags: ['--strict', '--optimize-vnni', '--force-pcore'],
246:     fallback: () => ({ success: false, reason: 'Out of VNNI registers' })
247:   });
248: };

